using System.Net;using System.Net.Http.Headers;using System.Text.Json;
public class RaceDayApi(IHttpContextAccessor accessor,IConfiguration config){
 HttpClient Client(){var h=new HttpClientHandler{CookieContainer=new CookieContainer(),UseCookies=true};var c=new HttpClient(h){BaseAddress=new Uri(config["ApiSettings:BaseUrl"]!)};var cookie=accessor.HttpContext?.Session.GetString("ApiCookie");if(!string.IsNullOrEmpty(cookie))h.CookieContainer.SetCookies(c.BaseAddress!,cookie);return c;}
 public async Task<T?> Get<T>(string path){using var c=Client();using var r=await c.GetAsync(path);if(!r.IsSuccessStatusCode)return default;return await r.Content.ReadFromJsonAsync<T>();}
 public async Task<(bool ok,string body)> Send<T>(HttpMethod method,string path,T? data=null){using var c=Client();using var q=new HttpRequestMessage(method,path);if(data!=null)q.Content=JsonContent.Create(data);using var r=await c.SendAsync(q);return(r.IsSuccessStatusCode,await r.Content.ReadAsStringAsync());}
 public async Task<(bool ok,string body)> Login(string email,string password){using var c=Client();using var r=await c.PostAsJsonAsync("api/auth/login",new{email,password});if(!r.IsSuccessStatusCode)return(false,"Invalid login details.");if(r.Headers.TryGetValues("Set-Cookie",out var vals)){var ck=vals.FirstOrDefault(x=>x.StartsWith(".RaceDay.Session="));if(ck!=null)accessor.HttpContext!.Session.SetString("ApiCookie",ck.Split(';')[0]);}var d=await r.Content.ReadFromJsonAsync<JsonElement>();var s=accessor.HttpContext!.Session;s.SetInt32("UserID",d.GetProperty("userID").GetInt32());s.SetString("Role",d.GetProperty("role").GetString()??"");s.SetString("FullName",d.GetProperty("fullName").GetString()??"");return(true,"");}
 public async Task<(bool ok,string body)> Upload(string path,IFormFile file){using var c=Client();using var form=new MultipartFormDataContent();await using var stream=file.OpenReadStream();using var sc=new StreamContent(stream);sc.Headers.ContentType=new MediaTypeHeaderValue(file.ContentType);form.Add(sc,"file",Path.GetFileName(file.FileName));using var r=await c.PostAsync(path,form);return(r.IsSuccessStatusCode,await r.Content.ReadAsStringAsync());}
}